args.command:
python3 - <<'PY'
import os
terms=('attachment','stale','refresh','presign','external','ticker','interval','schedule')
for root, dirs, files in os.walk('.'):
    dirs[:]=[d for d in dirs if d not in {'.git','node_modules'}]
    for f in files:
        p=os.path.join(root,f)
        try: data=open(p,errors='ignore').read().splitlines()
        except: continue
        for i,line in enumerate(data,1):
            if any(t in line.lower() for t in terms): print(f'{p}:{i}:{line}')
PY

